// MAIN //

/**
* Serializes an unsigned 64-bit integer as a string in the specified base.
*
* @private
* @param {number} base - The radix (base) to use for string conversion
* @returns {string} The serialized unsigned 64-bit integer as a string.
*
* **Note**
* This implementation handles 64-bit unsigned integers represented as either a BigInt or a pair of 32-bit words ([high, low]).
* For non-BigInt values, the conversion uses a precomputed POWERMAP to select a divisor and chunk size for efficient base conversion.
* The divisor values are chosen to be close to powers of 2^32 for each supported base, which is an unusual but efficient approach for chunked conversion.
* The function pads the lower chunk with leading zeros to ensure correct digit alignment.
*/
function toString( base ) { // eslint-disable-line stdlib/no-redeclare
	// eslint-disable-next-line no-undefined
	if ( base === undefined ) {
		base = 10;
	}
	// TODO: validate base range (between 2 and 36)
	if ( typeof this.value === 'bigint' ) {
		return this.value.toString( base );
	}

	var qr = divmod( this.value, POWERMAP[ base ].divisor );
	var sq = qr[ 0 ].toString( base );
	var sr = qr[ 1 ].toString( base );
	if ( sq === '0' ) {
		sq = '';
	}
	sr = lpad( sr, POWERMAP[ base ].power, '0' );
	return sq + sr;
}

/**
* Performs division and modulo for an unsigned 64-bit integer represented as high-low words.
*
* @private
* @param {Uint32Array|Array<number>} words - [high, low] 32-bit words
* @param {number} divisor - positive integer close to `2^32`
* @returns {Array<number>} [ quotient, remainder ]
*
* @example
* var x = divmod( [ 0, 5 ] );
* // returns [ 0, NaN ]
*/
function divmod( words, divisor ) {
	var hi = words[0] >>> 0;
	var lo = words[1] >>> 0;

	var quo = ( hi / divisor ) >>> 0;
	var rem = hi - ( divisor * quo );
	var qrd;

	if (divisor === 0x100000000) {
		return [ hi, lo ];
	}

	rem = ( rem * TWO_16 ) + ( lo >>> 16 );
	qrd = ( rem / divisor ) >>> 0;

	quo = ( quo * TWO_16 ) + qrd;
	rem -= divisor * qrd;

	rem = ( rem * TWO_16 ) + ( lo & 0xffff );
	qrd = ( rem / divisor ) >>> 0;

	quo = ( quo * TWO_16 ) + qrd;
	rem -= divisor * qrd;

	return [quo, rem];
}


// EXPORTS //

module.exports = toString;
